import { defineConfig } from "vitest/config";

export default defineConfig({
  test: {
    globals: true,
    environment: "node",
    include: ["tests/**/*.test.ts"],
    coverage: {
      provider: "v8",
      include: ["src/**/*.ts"],
      // server.ts is the process entrypoint (starts Fastify, binds ports);
      // it is exercised by running the app, not by unit tests.
      // generated/prisma/** is Prisma-generated client code (see the
      // "generated by Prisma. Do not edit directly" header in those files);
      // it ships from `prisma generate` and is not hand-written logic to test.
      // runnerTypes.ts contains only `export interface` declarations, which
      // erase to an empty JS module at compile time; even a dynamic import
      // that forces Node to load the compiled module cannot get the v8
      // coverage provider to attribute coverage to it (a module with zero
      // executable statements has nothing for v8 to instrument), so it is
      // permanently reported as a phantom 0% despite having no behavior to
      // test (verified: tests/runtime/runnerTypes.test.ts exercises every
      // exported type's shape and dynamically imports the module).
      exclude: ["src/server.ts", "src/generated/prisma/**", "src/runtime/runnerTypes.ts"],
      reporter: ["text", "json-summary", "html"],
      reportsDirectory: "coverage",
    },
  },
});
